// Branded report templates (P1-033, meeting T1 ~1418): A4 page and receipt-style (80 mm) views of any report with the
// venue logo, name, branch, date range, generated by, asOf, provisional flag, definitions + versions and a page footer.
// The logo/header/footer come from the venue document template (r3B DocTemplate) when set. src/ui/doc/** did not exist
// when this was built, so the header pieces are local here (to swap for the shared ones later).
import React from 'react';
import { createPortal } from 'react-dom';
import { Printer, X, FileText, ReceiptText } from 'lucide-react';
import { Button, SegmentedControl, DateTime } from '../../ui';
import { t, L } from '../../i18n';
import { fmt, statusText, Amt } from './parts';

type Paper = 'A4' | 'RECEIPT';
export function TemplatePreview({ run, onClose }: { run: any; onClose: () => void }) {
  const [paper, setPaper] = React.useState<Paper>('A4');
  const h = run.header;
  const v = h.venue;
  const sections: any[] = run.sections ?? [];
  const print = () => {
    document.body.classList.add('printing-report');
    setTimeout(() => { window.print(); setTimeout(() => document.body.classList.remove('printing-report'), 500); }, 50);
  };
  const receipt = paper === 'RECEIPT';
  const page = (
    <div id="report-print-area" dir="rtl" data-fb="report-template" className={receipt ? 'mx-auto bg-white text-black shadow-xl p-3 font-mono text-[11px] leading-snug' : 'mx-auto bg-white text-black shadow-xl p-8 text-[12px]'} style={{ width: receipt ? (v.template?.paper === '58MM' ? 220 : 302) : 794, minHeight: receipt ? undefined : 1123 }}>
      <div className={receipt ? 'text-center space-y-0.5 border-b border-dashed border-black pb-2' : 'flex items-start justify-between gap-4 border-b-2 border-black pb-3'}>
        <div className={receipt ? '' : 'flex items-center gap-3'}>
          {v.template?.logo ? <img src={v.template.logo} alt="" className={receipt ? 'mx-auto max-h-14' : 'h-16'} /> : <div className={receipt ? 'mx-auto w-12 h-12 rounded-full border-2 border-black flex items-center justify-center font-black' : 'w-16 h-16 rounded-full border-2 border-black flex items-center justify-center text-xl font-black'}>{(v.business.name || 'N').slice(0, 1)}</div>}
          <div>
            <div className={receipt ? 'font-bold text-[13px]' : 'text-xl font-black'}>{v.business.name}</div>
            <div>{v.branches.map((b: any) => b.name).join('، ')}</div>
            {v.business.taxNumber && <div>{t('الرقم الضريبي')}: <span className="num">{v.business.taxNumber}</span></div>}
            {v.template?.header?.map((l: string, i: number) => <div key={i}>{l}</div>)}
          </div>
        </div>
        <div className={receipt ? 'pt-1' : 'text-end'}>
          <div className={receipt ? 'font-bold' : 'text-lg font-bold'}>{L(h.title)}</div>
          <div>{t('اليوم التجاري')}: <span className="num">{h.period.from}{h.period.to !== h.period.from ? ` → ${h.period.to}` : ''}</span></div>
          <div className="text-[10px]">{t('من 4 الفجر لـ 4 الفجر بتوقيت القاهرة')}</div>
          <div>{h.provisional ? t('مبدئي') : t('نهائي (مقفول)')} · {t('المطابقة')}: {statusText(h.reconciliation.status)}</div>
        </div>
      </div>
      <div className="space-y-3 mt-3">
        {sections.map((s) => (
          <div key={s.id} className="break-inside-avoid">
            <div className={receipt ? 'font-bold border-b border-dashed border-black mt-2' : 'font-bold text-[13px] mb-1'}>{L(s.title)}</div>
            <table className="w-full border-collapse">
              {!receipt && <thead><tr>{s.columns.map((c: string, i: number) => <th key={i} className="text-start border-b border-black py-1 px-1 font-bold">{c}</th>)}</tr></thead>}
              <tbody>{s.rows.slice(0, receipt ? 20 : 40).map((r: any[], i: number) => (
                <tr key={i} className={receipt ? '' : 'border-b border-gray-300'}>{r.map((c, j) => <td key={j} className={receipt ? (j === r.length - 1 ? 'text-end num' : '') : `py-0.5 px-1 ${j > 0 ? 'num' : ''}`}>{c === 'CAPABILITY_NOT_AVAILABLE' ? t('مش متاح') : typeof c === 'string' && /^-?\d+\.\d{4}$/.test(c) ? <Amt v={c} /> : String(c ?? '')}</td>)}</tr>
              ))}</tbody>
            </table>
          </div>
        ))}
      </div>
      <div className={receipt ? 'mt-3 border-t border-dashed border-black pt-2 text-center text-[10px] space-y-0.5' : 'mt-6 border-t border-black pt-2 text-[10px] flex justify-between gap-4'}>
        <div>{t('اتطلع بواسطة')}: {v.generatedBy ?? '—'} · {t('لحد')} <DateTime v={h.asOf} /></div>
        <div>{t('التعريفات')}: {h.metrics.slice(0, 6).map((m: any) => `${L(m.label)} v${m.version}`).join('، ')}{h.metrics.length > 6 ? ' …' : ''}</div>
        {v.template?.footer?.map((l: string, i: number) => <div key={i}>{l}</div>)}
        <div className="num">{t('صفحة 1 من 1')} · nerdPOS</div>
      </div>
    </div>
  );
  return createPortal(
    <div id="report-print-root" className="fixed inset-0 top-12 z-[60] overlay-panel flex flex-col">
      <style>{`@media print { body.printing-report > *:not(#report-print-root) { display: none !important; } body.printing-report #report-print-root { position: static !important; inset: auto !important; } body.printing-report #report-print-root .no-print { display: none !important; } #report-print-area { box-shadow: none !important; } @page { size: ${receipt ? '80mm auto' : 'A4'}; margin: ${receipt ? '2mm' : '12mm'}; } }`}</style>
      <div className="flex flex-col h-full">
        <div className="no-print flex items-center gap-2 px-4 py-2 surface-2 border-b line">
          <SegmentedControl size="sm" value={paper} onChange={setPaper} options={[{ id: 'A4', label: t('صفحة A4'), icon: <FileText className="w-4 h-4" />, fb: 'template:a4' }, { id: 'RECEIPT', label: t('شكل الإيصال'), icon: <ReceiptText className="w-4 h-4" />, fb: 'template:receipt' }]} />
          <span className="text-xs text-dim">{t('اللوجو والهيدر والفوتر من «قالب الإيصال والمستندات» لو متظبط.')}</span>
          <span className="flex-1" />
          <Button size="sm" variant="primary" onClick={print} data-fb="template:print"><Printer className="w-4 h-4" />{t('اطبع / احفظ PDF')}</Button>
          <Button size="sm" variant="ghost" onClick={onClose} data-fb="template:close"><X className="w-4 h-4" /></Button>
        </div>
        <div className="flex-1 overflow-auto p-6 bg-neutral-500/30">{page}</div>
      </div>
    </div>,
    document.body,
  );
}
